package com.googlecode.javaewah.datastructure;



public final class PriorityQ<T> {
    final T[] a;
    int lastIndex;
    final Comparator<T> comp;

    @SuppressWarnings("unchecked")
    public PriorityQ(final int maxSize, final Comparator<T> c) {
        this.a = (T[]) new Object[maxSize + 1];
        this.lastIndex = 0;
        this.comp = c;
    }

    public int size() {
        return this.lastIndex;
    }

    private int compare(T a, T b) {
        return this.comp.compare(a, b);
    }

    public void toss(final T t) {
        this.a[++this.lastIndex] = t;
    }

    public T peek() {
        return this.a[1];
    }

    public void buildHeap() {
        for (int i = this.lastIndex / 2; i > 0; --i) {
            percolateDown(i);
        }
    }

    public void percolateDown() {
        percolateDown(1);
    }

    private void percolateDown(int i) {
        T ai = this.a[i];
        while (true) {
            int l = 2 * i;
            int r = l + 1;
            int smallest = i;

            if (r <= this.lastIndex) { if (compare(this.a[l], ai) < 0) { smallest = l;
                    if (compare(this.a[r], this.a[smallest]) < 0)
                        smallest = r;
                } else if (compare(this.a[r], ai) < 0)
                    smallest = r;
            } else {if ((l <= this.lastIndex)
                        && (compare(this.a[l], ai) < 0))
                    smallest = l;
            }
            if (i != smallest) {
                this.a[i] = this.a[smallest]; i = smallest;
            } else {
                this.a[smallest] = ai;
                return;
            }
        }
    }

    public T poll() {
        T ans = this.a[1];
        this.a[1] = this.a[this.lastIndex--];
        percolateDown(1);
        return ans;
    }

    public boolean isEmpty() {
        return this.lastIndex == 0;
    }
}
