package com.newweb.model.business;












@Entity
@Table(name="t_order_bxgs")
public class OrderBxg {

    private int ID;
    private Order order;
    private Bxg bxg;
    private double count;
    private String operation; @Column
    public String getOperation() {
        return operation;
    }
    public void setOperation(String operation) {
        this.operation = operation;
    }
    @Id
    @GeneratedValue(strategy=GenerationType.AUTO)
    @Column(name="id")
    public int getID() {
        return ID;
    }
    public void setID(int iD) {
        ID = iD;
    }

    @ManyToOne
    @JoinColumn(name="orderID")
    public Order getOrder() {
        return order;
    }
    public void setOrder(Order order) {
        this.order = order;
    }

    @ManyToOne
    @JoinColumn(name="bxgID")
    public Bxg getBxg() {
        return bxg;
    }
    public void setBxg(Bxg bxg) {
        this.bxg = bxg;
    }

    @Column
    public double getCount() {
        return count;
    }
    public void setCount(double count) {
        this.count = count;
    }

    @Override
    public boolean equals(Object obj) {
        OrderBxg o = (OrderBxg) obj;
        if(bxg.getID() == o.getBxg().getID())
            return true;
        return false;           
    }

    @Override
    public int hashCode() {
        return bxg.getID();
    }

}
