package chap12;




public class SimpleAnimation {

    int x = 70;
    int y = 70;

    public static void main (String[] args) {
       SimpleAnimation gui = new SimpleAnimation ();
       gui.go();
   }

   public void go() {
       JFrame frame = new JFrame();
       frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);

       MyDrawPanel drawPanel = new MyDrawPanel();       

       frame.getContentPane().add(drawPanel);
       frame.setSize(300,300);
       frame.setVisible(true);


       for (int i = 0; i < 130; i++) {

          x++;
          y++;

          drawPanel.repaint();

          try {
            Thread.sleep(50);
          } catch(Exception ex) { }
       }

   }class MyDrawPanel extends JPanel {

       public void paintComponent(Graphics g) {
          g.setColor(Color.white);
          g.fillRect(0,0,this.getWidth(), this.getHeight());

          g.setColor(Color.green);
          g.fillOval(x,y,40,40);

       }
    }  ,24,180

public class PosicionDigitoConWhile {

public static void main(String[] args) {
Scanner teclado = new Scanner(System.in);

    long numIntrod;
    long digito;
    long reves = 0;
    int posicion = 1;

    System.out.println("Introduce un numro");
    numIntrod = teclado.nextLong();

    System.out.println("Introduce un digito");
    digito = teclado.nextLong();

    System.out.println("-------------------------------------------------------");

    while (numIntrod > 0){
        reves = (reves * 10) + (numIntrod % 10);
        numIntrod = numIntrod / 10;
    } 

    while (reves > 0){
        if ((reves % 10) == digito){
            System.out.println("El digito esta en la posicion:" + posicion);
        }
        reves = reves / 10;
        posicion++;
    }
  }
