            return localAddr;
        return ssdpUniSock.getLocalAddress().getHostAddress();
    }

    public boolean open()
    {
        close();

        try {
            ssdpUniSock = new DatagramSocket();
        }
        catch (Exception e) {
            Debug.warning(e);
            return false;
        }

        return true;
