public class ScreenRollView extends SurfaceView implements SurfaceHolder.Callback{

    HDZGActivity activity;
    Bitmap bmpScroll;Bitmap bmpBack;DrawThread drawThread;ScreenRollThread screenRollThread;float textSize = 23f;int scrollStartX = 320;int scrollStartY = 60;int characterEachLine = 10;int characterSpanX = 36;int characterSpanY = 25;int characterNumber = 1;int textStartX=237;int textStartY=135;int startChar=0;int maxChar = 60;int alpha = 255;int status;String msg = "¶«ÖÜÄ©Äê£¬ÖÜÊÒÒÑ¾­Ãû´æÊµÍö£¬ÌìÏÂÖ»ÊÇÔÚÃûÒåÉÏ¹éÓÚÒ»¼Ò¡£¸÷¸öÖîºî¹úÖ®¼äµÄÕ½ÕùÔçÒÑÊÇ·é»ðÁ¬Ìì£¬¸÷ÖÖÍÌ²¢"
        +"ºÍ½áÃËÂÅ¼û²»ÏÊ¡£²»ÖªÄãÄÜ·ñÔÚÕâÂÒÊÀ¿¿×Å×Ô¼ºµÄ²Å¸ÉÄ±ÂÔÎª×Ô¼ºÊØ×¡Ò»·½ÍÁµØ£¬ÉõÖÁÊÇºÍÆäËûÖîºî¹úÒ»Ñù£¬ÖðÂ¹"
        +"ÖÐÔ­£¬²¢ÍÌ°Ë»Ä£¿";

    public ScreenRollView(HDZGActivity activity) {
        super(activity);
        this.activity = activity;
        getHolder().addCallback(this);
        drawThread = new DrawThread(getHolder());
        screenRollThread = new ScreenRollThread(this);
        initBitmap(getResources());
        status = 1;
    }
    public void initBitmap(Resources r){
        bmpScroll = BitmapFactory.decodeResource(r, R.drawable.scroll);}
    public void onDraw(Canvas canvas){
        canvas.drawColor(Color.BLACK);
        Paint paint = new Paint();
        paint.setAlpha(alpha);
        switch(status){
        case 3:case 2:canvas.drawBitmap(bmpScroll, scrollStartX, scrollStartY, paint);
            paint.setTextSize(textSize);
            paint.setAntiAlias(true);
            paint.setARGB(alpha, 234, 234, 234);
            if(characterNumber > maxChar){startChar += characterEachLine;characterNumber -= characterEachLine;
            }
            int lines = characterNumber/characterEachLine+(characterNumber%characterEachLine==0?0:1);for(int i=0;i<lines;i++){
                if(i == lines-1){int n = characterNumber - characterEachLine*(lines -1);for(int j=0;j<n-1;j++){
                        canvas.drawText(
                                msg.charAt(startChar+i*characterEachLine+j)+"",
                                textStartX-i*characterSpanX,
                                textStartY+j*characterSpanY,
                                paint);
                    }
                }
                else{for(int j=0;j<characterEachLine;j++){
                        canvas.drawText(
                                msg.charAt(startChar+i*characterEachLine+j)+"",
                                textStartX-i*characterSpanX,
                                textStartY+j*characterSpanY,
                                paint);
                    }
                }
            }
            break;
        case 1:canvas.drawBitmap(bmpScroll, scrollStartX, scrollStartY, paint);
            break;
        }
    }

    public void surfaceChanged(SurfaceHolder holder, int format, int width,
            int height) {
    }

    public void surfaceCreated(SurfaceHolder holder) {
        if(!drawThread.isAlive()){
            drawThread.start();
        }
        screenRollThread.flag = true;
        if(!screenRollThread.isAlive()){screenRollThread.start();
        }
    }

    public void surfaceDestroyed(SurfaceHolder holder) {
        drawThread.setFlag(false);
    }

    class DrawThread extends Thread{private int sleepSpan = ConstantUtil.GAME_VIEW_SLEEP_SPAN;private SurfaceHolder surfaceHolder;
        private boolean flag = true;
        public DrawThread(SurfaceHolder surfaceHolder) {this.surfaceHolder = surfaceHolder;
        }

        public void setFlag(boolean flag) {this.flag = flag;
        }

        public void run() {
            Canvas c;
            while(flag){
                    c = null;
                    try {
                        c = this.surfaceHolder.lockCanvas(null);
                        synchronized (this.surfaceHolder) {
                            onDraw(c);
                        }
                    } finally {
                        if (c != null) {
                            this.surfaceHolder.unlockCanvasAndPost(c);
                        }
                    }
                    try{
                        Thread.sleep(sleepSpan);}
                    catch(Exception e){
                        e.printStackTrace();
                    }
                }
                try{
                    Thread.sleep(1500);}
                catch(Exception e){
                    e.printStackTrace();
                }
        }
    }
